'use client';

import { useEffect, useState } from 'react';
import { BrowserProvider, Contract, formatEther } from 'ethers';
import { CONTRACT_ADDRESSES } from '@/lib/constants';
import Link from 'next/link';

declare global {
  interface Window {
    ethereum?: any;
  }
}

const NEXTIA_ABI = [
  'function balanceOf(address account) external view returns (uint256)',
];

export default function Home() {
  const [balance, setBalance] = useState('0');
  const [address, setAddress] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const connectWallet = async () => {
      try {
        if (!window.ethereum) {
          setLoading(false);
          return;
        }
        const provider = new BrowserProvider(window.ethereum);
        const signer = await provider.getSigner();
        const userAddress = await signer.getAddress();
        setAddress(userAddress);

        const tokenContract = new Contract(
          CONTRACT_ADDRESSES.TOKEN,
          NEXTIA_ABI,
          signer
        );

        const bal = await tokenContract.balanceOf(userAddress);
        setBalance(formatEther(bal));
      } catch (error) {
        console.error('Error:', error);
      } finally {
        setLoading(false);
      }
    };
    connectWallet();
  }, []);

  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#000', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '16px' }}>
      <div style={{ textAlign: 'center', maxWidth: '600px' }}>
        <h1 style={{ fontSize: '48px', fontWeight: 'bold', marginBottom: '32px' }}>NextiaToken DApp</h1>
        {loading ? (
          <p style={{ fontSize: '20px', color: '#999' }}>Cargando...</p>
        ) : address ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
            <div style={{ backgroundColor: '#1a1a1a', padding: '32px', borderRadius: '8px' }}>
              <p style={{ color: '#999', marginBottom: '8px' }}>Wallet conectada:</p>
              <p style={{ fontFamily: 'monospace', fontSize: '14px', wordBreak: 'break-all', color: '#0ff' }}>{address}</p>
            </div>
            <div style={{ backgroundColor: '#1a1a1a', padding: '32px', borderRadius: '8px' }}>
              <p style={{ color: '#999', marginBottom: '8px' }}>Tu balance de NXT:</p>
              <p style={{ fontSize: '48px', fontWeight: 'bold', color: '#0ff' }}>{balance} NXT</p>
            </div>
            <Link href="/staking">
              <button style={{ width: '100%', padding: '16px', backgroundColor: '#6b21a8', color: '#fff', fontWeight: 'bold', fontSize: '18px', borderRadius: '8px', border: 'none', cursor: 'pointer' }}>
                📈 Ir a Staking
              </button>
            </Link>
            <p style={{ fontSize: '12px', color: '#666' }}>✓ Hardhat conectado</p>
          </div>
        ) : (
          <p style={{ fontSize: '20px', color: '#f00' }}>Conecta MetaMask a Hardhat (localhost)</p>
        )}
      </div>
    </div>
  );
}
